                # Handle '?'
                new_j1 = j + 1
                if new_j1 <= n:
                    curr[new_j1] = (curr[new_j1] + prev[j]) % MOD
                new_j2 = j - 1
                if new_j2 >= 0:
                    curr[new_j2] = (curr[new_j2] + prev[j]) % MOD
        prev = curr
    print(prev[0] % MOD)

