import sys

def main():
    data = sys.stdin.read().split()
    ptr = 0
    Q = int(data[ptr])
    ptr += 1
    count_map = {}
    distinct_count = 0
    output = []
    for _ in range(Q):
        query_type = data[ptr]
        if query_type == '1' or query_type == '2':
            x = int(data[ptr + 1])
            ptr += 2
            if query_type == '1':
                if count_map.get(x, 0) == 0:
                    distinct_count += 1
                count_map[x] = count_map.get(x, 0) + 1
            else:
                count_map[x] -= 1
                if count_map[x] == 0:
                    distinct_count -= 1
        else:
            ptr += 1
            output.append(str(distinct_count))
    print('\n'.join(output))

if __name__ == '__main__':
    main()
```

